css:
        print-format {
            size: A4 landscape;
            margin: 5mm;
        }

        body {
            font-family: 'DejaVu Sans', 'Calibri', Arial, sans-serif;
            font-size: 9pt;
            line-height: 1.3;
            color: #000;
            margin: 0;
            padding: 0;
        }

        .document-header {
            text-align: right;
            margin-bottom: 10px;
            font-size: 10pt;
        }

        .document-title {
            text-align: center;
            font-weight: bold;
            font-size: 11pt;
            margin: 15px 0 5px 0;
            text-transform: uppercase;
        }

        .document-subtitle {
            text-align: center;
            font-size: 10pt;
            margin: 5px 0;
        }

        .department-info {
            text-align: center;
            font-size: 9pt;
            margin: 5px 0 15px 0;
        }

        .approval-section {
            text-align: right;
            margin: 10px 0;
            font-size: 9pt;
        }

        .main-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 15px;
            font-size: 8.5pt;
        }

        .main-table td,
        .main-table th {
            border: 1px solid #000;
            padding: 4px 6px;
            vertical-align: top;
        }

        .main-table th {
            background-color: #f0f0f0;
            font-weight: bold;
            text-align: center;
        }

        .header-row {
            background-color: #e8e8e8;
            font-weight: bold;
        }

        .label-cell {
            background-color: #f5f5f5;
            font-weight: bold;
            width: 180px;
        }

        .supplier-header {
            background-color: #d9d9d9;
            font-weight: bold;
            text-align: center;
        }

        .date-cell {
            text-align: center;
            background-color: #fff;
        }

        .supplier-info {
            font-size: 8pt;
            line-height: 1.4;
        }

        .price-cell {
            text-align: right;
            font-weight: bold;
        }

        .center-cell {
            text-align: center;
        }

        .total-row {
            background-color: #f0f0f0;
            font-weight: bold;
        }

        .additional-info-row {
            background-color: #fafafa;
        }

        .conclusion-section {
            margin-top: 15px;
            font-size: 9pt;
            line-height: 1.4;
        }

        .empty-cell {
            background-color: #fff;
        }

        .no-border-top {
            border-top: none;
        }
